def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    weak_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) < 120 or opp.get('hp', 0) <= 3:
                weak_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 120 and opp.get('budget', 0) >= 200:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.55
    elif hp <= 6:
        danger += 0.2

    if no_water_days >= 2:
        danger += 1.0
    elif no_water_days >= 1:
        danger += 0.45

    if supply <= 17:
        danger += 0.35
    elif supply <= 19:
        danger += 0.15

    if danger >= 1.4:
        bid = 146.0 if highest_prev >= 130 else 118.0
    elif danger >= 0.8:
        bid = 92.0 + 18.0 * scarcity
    else:
        if rich_aggressive >= 2:
            bid = 12.0 + 10.0 * scarcity
        elif highest_prev >= 120:
            bid = 18.0 + 12.0 * scarcity
        elif avg_prev >= 70:
            bid = 35.0 + 10.0 * scarcity
        else:
            bid = 48.0 + 12.0 * scarcity

    if weak_opponents >= 2 and danger < 0.8:
        bid *= 0.8

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.85

    if budget < 90:
        if danger >= 1.4:
            bid = min(bid, budget)
        else:
            bid = min(bid, max(8.0, budget * 0.45))

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Determine how aggressive opponents were yesterday from their last bid
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Base bid level: aim to compete without exhausting budget
    # Supply is split among bidders; higher supply usually means less need to overbid.
    # Use supply to set a target bid fraction.
    if supply >= 22.0:
        target_frac = 0.55
    elif supply >= 18.0:
        target_frac = 0.62
    else:
        target_frac = 0.70

    # React to yesterday aggression: if they were close to cap, raise slightly
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Their observed maxes were around 147; treat that as near-cap pressure
        if highest_prev_bid >= 140.0:
            target_frac += 0.10
        elif highest_prev_bid >= 125.0:
            target_frac += 0.05

    # If I'm in danger, spend more
    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Emergency escalation
    if my_hp <= 1 or no_water_days >= 2:
        target_frac = max(target_frac, 0.85)
    elif my_hp <= 3:
        target_frac = max(target_frac, 0.70)

    bid = DAILY_SALARY * target_frac

    # Ensure we never bid more than budget
    if my_budget <= 0:
        return 0.0

    if bid > my_budget:
        bid = my_budget

    # Keep a small reserve for later if not urgent
    if my_hp > 3 and no_water_days < 2:
        reserve = 0.15 * my_budget
        if bid > my_budget - reserve:
            bid = my_budget - reserve

    # Clamp bid to non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Compute number of water units our requirement can cover
    max_units = int(supply // WATER_REQ)  # supply is float, convert to int

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        # If someone bid very high yesterday, they might be desperate
        if max_yesterday_bid >= DAILY_SALARY * 0.85:
            # If we are healthy, lowball; if low on HP, bid high
            if hp > 3:
                return min(budget, DAILY_SALARY * 0.3)
            else:
                return min(budget, DAILY_SALARY * 0.95)
        else:
            # Otherwise, try to stay competitive but not exceed budget
            target_bid = max(DAILY_SALARY * 0.5, max_yesterday_bid + 1.0)
            return min(budget, target_bid)

    # No previous traces (first day or new opponents)
    if hp <= 2:
        return min(budget, DAILY_SALARY * 0.9)
    # Default: moderate bid based on supply availability
    if max_units >= 1:
        # There is at least one water unit for each alive player? estimate
        # bid around 0.6 of salary to be safe
        return min(budget, DAILY_SALARY * 0.6)
    else:
        # Supply scarce, bid high to secure water
        return min(budget, DAILY_SALARY * 0.85)
